package fr.boubou.widget

import android.graphics.BitmapFactory
import android.util.Base64

/** Real photograph of Boubou, provided by its owner; resized for a home-screen widget. */
object BoubouPhoto {
    fun bitmap() = Base64.decode("", Base64.DEFAULT).let { bytes -> BitmapFactory.decodeByteArray(bytes, 0, bytes.size) }
}
